H.background();
const r = P.r;
const cam = H.cam3d({ scale: 40, dist: 11, pitch: -0.35, cy: 300 });
cam.yaw = 0.4 * t;
cam.grid(6, 1);
cam.sphere([0, 0, 0], r, { color: H.colors.accent });
const N = 32;
for (let m = 1; m <= 3; m++) {
  const phi = (m / 4) * Math.PI - Math.PI / 2;
  const yy = r * Math.sin(phi), rr = r * Math.cos(phi);
  const pts = [];
  for (let i = 0; i <= N; i++) { const a = (i / N) * Math.PI * 2; pts.push([rr * Math.cos(a), yy, rr * Math.sin(a)]); }
  cam.path(pts, { color: "rgba(255,255,255,0.28)", width: 1 });
}
for (let m = 0; m < 4; m++) {
  const lon = (m / 4) * Math.PI;
  const pts = [];
  for (let i = 0; i <= N; i++) { const a = (i / N) * Math.PI * 2; pts.push([r * Math.cos(a) * Math.cos(lon), r * Math.sin(a), r * Math.cos(a) * Math.sin(lon)]); }
  cam.path(pts, { color: "rgba(255,255,255,0.18)", width: 1 });
}
cam.line([0, 0, 0], [r, 0, 0], { color: H.colors.accent2, width: 2 });
const V = (4 / 3) * Math.PI * r * r * r;
const SA = 4 * Math.PI * r * r;
H.text("Sphere: V = (4/3) pi r^3", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("volume grows with the cube of r; surface area 4 pi r^2 grows with the square", 24, 52, { color: H.colors.sub, size: 13 });
H.text("r = " + r.toFixed(1) + "   V = " + V.toFixed(1) + "   SA = " + SA.toFixed(1), 24, 74, { color: H.colors.accent2, size: 13 });
